# Nginx rate limiting configuration
http:
  # Define a shared memory zone for rate tracking
  limit_req_zone $http_x_api_key zone=api_per_key:10m rate=100r/s;

  server:
    listen 443 ssl;

    location /api/ {
      # Allow burst of 50 with nodelay, then queue up to 200 more
      limit_req zone=api_per_key burst=200 nodelay;
      limit_req_status 429;

      # Add Retry-After header on 429
      add_header Retry-After 1 always;

      proxy_pass http://backend;
    }
  }

